/**
 * Swift Woo - Variation & Multi-Color Swatch JS (ichoicebd.com 1:1 style)
 * - Clean pill buttons with top-right circular ✓ badge
 * - Single-color row with inline amber hint banner for 2/3 pcs multi-color selection
 * - 100% Native WooCommerce <select> & variations_form compatible (visually hidden)
 * - Auto-selects first in-stock variation on load
 * - Zero hook modifications, scanner-safe, zero eval
 * @version 1.0.32
 */
( function () {
	'use strict';

	function initVariations() {
		const variationForm = document.querySelector( 'form.variations_form' );
		if ( ! variationForm ) return;

		// Bengali & English numeral normalizer
		function extractCount( val ) {
			if ( ! val ) return 1;
			const bnMap = { '০': '0', '১': '1', '২': '2', '৩': '3', '৪': '4', '৫': '5', '৬': '6', '৭': '7', '৮': '8', '৯': '9' };
			const cleanStr = String( val ).replace( /[০-৯]/g, function ( d ) { return bnMap[ d ] || d; } );
			const match = cleanStr.match( /\d+/ );
			return match ? parseInt( match[ 0 ], 10 ) : 1;
		}

		const selects = Array.from( variationForm.querySelectorAll( 'select[data-attribute_name], select[name^="attribute_"]' ) );
		if ( ! selects.length ) return;

		// Identify which select is Package and which is Color
		let packageSelect = null;
		let colorSelect = null;

		selects.forEach( function ( select ) {
			const row = select.closest( 'tr' );
			const labelElem = row ? row.querySelector( 'th.label label, label' ) : null;
			const attrTitle = labelElem ? labelElem.textContent.replace( /[:：]/g, '' ).trim() : '';
			let attrName = select.getAttribute( 'data-attribute_name' ) || select.getAttribute( 'name' ) || '';
			try { attrName = decodeURIComponent( attrName ); } catch ( e ) {}
			const combined = ( attrName + ' ' + attrTitle ).toLowerCase();

			if ( /pis|pack|package|quantity|qty|প্যাকেজ|পিস|পরিমাণ/i.test( combined ) ) {
				packageSelect = select;
			} else if ( /color|colour|rang|কালার|রং/i.test( combined ) ) {
				colorSelect = select;
			}
		} );

		// Fallback if not matched by name: first select is color, second is package or vice versa
		if ( ! packageSelect && selects.length > 1 ) {
			packageSelect = selects.find( function ( s ) { return s !== colorSelect; } );
		}
		if ( ! colorSelect && selects.length > 1 ) {
			colorSelect = selects.find( function ( s ) { return s !== packageSelect; } );
		}

		let activePackageCount = 1;
		let selectedColors = [];
		let colorHintBanner = null;

		// Create hidden inputs container for extra colors
		let extraColorsWrap = document.getElementById( 'swift-extra-colors-hidden-wrap' );
		if ( ! extraColorsWrap ) {
			extraColorsWrap = document.createElement( 'div' );
			extraColorsWrap.id = 'swift-extra-colors-hidden-wrap';
			variationForm.appendChild( extraColorsWrap );
		}

		function syncHiddenColorInputs() {
			extraColorsWrap.innerHTML = '';
			selectedColors.forEach( function ( colVal, idx ) {
				const hidden = document.createElement( 'input' );
				hidden.type = 'hidden';
				hidden.name = 'swift_colors[' + idx + ']';
				hidden.value = colVal;
				extraColorsWrap.appendChild( hidden );
			} );
		}

		function updateColorHintBanner() {
			if ( ! colorHintBanner ) return;
			if ( activePackageCount < 2 ) {
				colorHintBanner.style.display = 'none';
				return;
			}
			colorHintBanner.style.display = 'inline-block';
			const bnDigits = [ '০', '১', '২', '৩', '৪', '৫', '৬', '৭', '৮', '৯' ];
			const totalStr = bnDigits[ activePackageCount ] || activePackageCount;
			const currStr = bnDigits[ selectedColors.length ] || selectedColors.length;

			if ( selectedColors.length >= activePackageCount ) {
				colorHintBanner.innerHTML = '✓ ' + totalStr + 'টি কালার সিলেক্ট করা হয়েছে (' + currStr + '/' + totalStr + ')';
				colorHintBanner.style.color = '#065f46';
				colorHintBanner.style.background = '#ecfdf5';
				colorHintBanner.style.borderColor = '#a7f3d0';
			} else {
				colorHintBanner.innerHTML = '✨ ' + totalStr + 'টি কালার সিলেক্ট করুন (' + currStr + '/' + totalStr + ')';
				colorHintBanner.style.color = '#b45309';
				colorHintBanner.style.background = '#fffbeb';
				colorHintBanner.style.borderColor = '#fde68a';
			}
		}

		/* ------------------------------------------------------------------
		 * Build Pill Buttons for each <select>
		 * ------------------------------------------------------------------ */
		selects.forEach( function ( select ) {
			const isPkg = ( select === packageSelect );
			const isCol = ( select === colorSelect );

			const wrapper = select.closest( '.value' ) || select.closest( 'td' ) || select.parentElement;

			// Hide native select visually
			select.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;opacity:0;pointer-events:none;';
			select.setAttribute( 'aria-hidden', 'true' );

			// Button container
			let btnContainer = wrapper.querySelector( '.swift-swatch-buttons' );
			if ( ! btnContainer ) {
				btnContainer = document.createElement( 'div' );
				btnContainer.className = 'swift-swatch-buttons ' + ( isPkg ? 'swift-pis-buttons' : 'swift-color-swatches' );
				btnContainer.setAttribute( 'role', 'group' );
				wrapper.appendChild( btnContainer );
			} else {
				btnContainer.innerHTML = '';
			}

			// If Color select, add the inline hint banner directly below buttons
			if ( isCol && ! colorHintBanner ) {
				colorHintBanner = document.createElement( 'div' );
				colorHintBanner.className = 'swift-color-hint';
				colorHintBanner.style.display = 'none';
				wrapper.appendChild( colorHintBanner );
			}

			const options = Array.from( select.options ).filter( function ( o ) { return o.value !== ''; } );

			options.forEach( function ( option ) {
				const btn = document.createElement( 'button' );
				btn.type = 'button';
				btn.className = 'swift-swatch-pill ' + ( isPkg ? 'swift-pis-btn' : 'swift-color-swatch' );
				btn.dataset.value = option.value;
				btn.dataset.label = option.textContent.trim();
				btn.textContent = option.textContent.trim();
				btn.setAttribute( 'aria-pressed', 'false' );

				if ( option.disabled ) {
					btn.disabled = true;
					btn.setAttribute( 'aria-disabled', 'true' );
					btn.classList.add( 'is-disabled' );
				}

				btn.addEventListener( 'click', function ( e ) {
					e.preventDefault();

					if ( isPkg ) {
						// Package selection: single select
						btnContainer.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
							b.classList.remove( 'is-active', 'active' );
							b.setAttribute( 'aria-pressed', 'false' );
						} );
						btn.classList.add( 'is-active', 'active' );
						btn.setAttribute( 'aria-pressed', 'true' );

						select.value = btn.dataset.value;
						select.dispatchEvent( new Event( 'change', { bubbles: true } ) );
						if ( window.jQuery ) window.jQuery( select ).trigger( 'change' );

						activePackageCount = extractCount( btn.dataset.value ) || extractCount( btn.dataset.label ) || 1;

						// Adjust selected colors if package count decreased
						if ( selectedColors.length > activePackageCount ) {
							selectedColors = selectedColors.slice( 0, activePackageCount );
						}
						// Refresh color button active classes
						if ( colorSelect ) {
							const colWrap = colorSelect.closest( '.value' ) || colorSelect.closest( 'td' ) || colorSelect.parentElement;
							if ( colWrap ) {
								colWrap.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( cb ) {
									if ( selectedColors.includes( cb.dataset.value ) ) {
										cb.classList.add( 'is-active', 'active' );
										cb.setAttribute( 'aria-pressed', 'true' );
									} else {
										cb.classList.remove( 'is-active', 'active' );
										cb.setAttribute( 'aria-pressed', 'false' );
									}
								} );
							}
						}
						syncHiddenColorInputs();
						updateColorHintBanner();

					} else if ( isCol ) {
						// Color selection
						if ( activePackageCount < 2 ) {
							// Single piece: single select
							btnContainer.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
								b.classList.remove( 'is-active', 'active' );
								b.setAttribute( 'aria-pressed', 'false' );
							} );
							btn.classList.add( 'is-active', 'active' );
							btn.setAttribute( 'aria-pressed', 'true' );

							selectedColors = [ btn.dataset.value ];
							select.value = btn.dataset.value;
							select.dispatchEvent( new Event( 'change', { bubbles: true } ) );
							if ( window.jQuery ) window.jQuery( select ).trigger( 'change' );

						} else {
							// Multi-piece (2 Pcs or 3 Pcs): multi-select toggle
							const val = btn.dataset.value;
							const idx = selectedColors.indexOf( val );

							if ( idx > -1 ) {
								// Already selected: un-toggle if more than 1 selected
								if ( selectedColors.length > 1 ) {
									selectedColors.splice( idx, 1 );
									btn.classList.remove( 'is-active', 'active' );
									btn.setAttribute( 'aria-pressed', 'false' );
								}
							} else {
								// Not selected: add
								if ( selectedColors.length < activePackageCount ) {
									selectedColors.push( val );
									btn.classList.add( 'is-active', 'active' );
									btn.setAttribute( 'aria-pressed', 'true' );
								} else {
									// Max reached: replace oldest
									const removedVal = selectedColors.shift();
									selectedColors.push( val );
									btnContainer.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
										if ( b.dataset.value === removedVal ) {
											b.classList.remove( 'is-active', 'active' );
											b.setAttribute( 'aria-pressed', 'false' );
										}
									} );
									btn.classList.add( 'is-active', 'active' );
									btn.setAttribute( 'aria-pressed', 'true' );
								}
							}

							// Primary color value for WooCommerce core variation engine
							if ( selectedColors.length > 0 ) {
								select.value = selectedColors[ 0 ];
								select.dispatchEvent( new Event( 'change', { bubbles: true } ) );
								if ( window.jQuery ) window.jQuery( select ).trigger( 'change' );
							}
						}

						syncHiddenColorInputs();
						updateColorHintBanner();

					} else {
						// Any other attribute: single select
						btnContainer.querySelectorAll( '.swift-swatch-pill' ).forEach( function ( b ) {
							b.classList.remove( 'is-active', 'active' );
							b.setAttribute( 'aria-pressed', 'false' );
						} );
						btn.classList.add( 'is-active', 'active' );
						btn.setAttribute( 'aria-pressed', 'true' );

						select.value = btn.dataset.value;
						select.dispatchEvent( new Event( 'change', { bubbles: true } ) );
						if ( window.jQuery ) window.jQuery( select ).trigger( 'change' );
					}
				} );

				btnContainer.appendChild( btn );
			} );

			// Auto-select first enabled option
			const firstEnabled = options.find( function ( o ) { return ! o.disabled; } );
			if ( firstEnabled ) {
				const firstBtn = Array.from( btnContainer.querySelectorAll( '.swift-swatch-pill' ) )
					.find( function ( b ) { return b.dataset.value === firstEnabled.value; } );
				if ( firstBtn ) {
					firstBtn.classList.add( 'is-active', 'active' );
					firstBtn.setAttribute( 'aria-pressed', 'true' );
					select.value = firstEnabled.value;
					select.dispatchEvent( new Event( 'change', { bubbles: true } ) );
					if ( window.jQuery ) window.jQuery( select ).trigger( 'change' );

					if ( isPkg ) {
						activePackageCount = extractCount( firstEnabled.value ) || extractCount( firstEnabled.textContent ) || 1;
					}
					if ( isCol ) {
						selectedColors = [ firstEnabled.value ];
						syncHiddenColorInputs();
					}
				}
			}
		} );

		updateColorHintBanner();

		/* ------------------------------------------------------------------
		 * Keep Buy Now button in sync with variation found events
		 * ------------------------------------------------------------------ */
		if ( window.jQuery ) {
			window.jQuery( variationForm ).on( 'found_variation', function ( event, variation ) {
				const buyNowBtn = variationForm.querySelector( '.swift-buy-now-btn' );
				if ( buyNowBtn && variation && variation.variation_id ) {
					buyNowBtn.dataset.variationId = variation.variation_id;
				}
			} );
		}
	}

	/* ------------------------------------------------------------------
	 * Initialization on DOMContentLoaded & pageshow
	 * ------------------------------------------------------------------ */
	if ( document.readyState === 'loading' ) {
		document.addEventListener( 'DOMContentLoaded', initVariations );
	} else {
		initVariations();
	}

	window.addEventListener( 'pageshow', function ( e ) {
		if ( e.persisted ) {
			const buyBtns = document.querySelectorAll( '.swift-buy-now-btn' );
			buyBtns.forEach( function ( btn ) {
				btn.disabled = false;
				btn.classList.remove( 'is-loading' );
			} );
		}
	} );

} )();
